package com.paymentplatform.transfer_service.domain;
import com.paymentplatform.transfer_service.api.ApiException;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tools.jackson.databind.ObjectMapper;import java.util.*;import java.time.*;
@Service public class TransferStore {
 private final JdbcTemplate jdbc;private final ObjectMapper json;public TransferStore(JdbcTemplate jdbc,ObjectMapper json){this.jdbc=jdbc;this.json=json;}
 public record Context(UUID senderCustomer,UUID recipientCustomer,UUID senderAccount,UUID recipientAccount,UUID feeAccount,UUID quoteId,long fee,long total,Instant quoteExpires,UUID riskId,Instant riskExpires,UUID reservationId,Instant reservationExpires){
  public Context risk(UUID id,Instant expiry){return new Context(senderCustomer,recipientCustomer,senderAccount,recipientAccount,feeAccount,quoteId,fee,total,quoteExpires,id,expiry,reservationId,reservationExpires);}
  public Context reservation(UUID id,Instant expiry){return new Context(senderCustomer,recipientCustomer,senderAccount,recipientAccount,feeAccount,quoteId,fee,total,quoteExpires,riskId,riskExpires,id,expiry);}
 }
 public record Row(UUID id,String actor,UUID sender,UUID recipient,long amount,long maxFee,String currency,String state,Context context,UUID journal,String lastCode,Instant createdAt,Instant updatedAt){}
 public record View(UUID id,UUID senderWalletId,UUID recipientWalletId,long amount,long maxFee,String currency,Long fee,String status,UUID journalId,String lastCode,Instant createdAt,Instant updatedAt){}
 public record Begin(Row row,boolean replayed){}
 public View view(Row row){return new View(row.id(),row.sender(),row.recipient(),row.amount(),row.maxFee(),row.currency(),row.context()==null?null:row.context().fee(),row.state(),row.journal(),row.lastCode(),row.createdAt(),row.updatedAt());}
 private Row read(java.sql.ResultSet r)throws java.sql.SQLException{String context=r.getString("context");return new Row(r.getObject("id",UUID.class),r.getString("actor_id"),r.getObject("sender_wallet",UUID.class),r.getObject("recipient_wallet",UUID.class),r.getLong("amount"),r.getLong("max_fee"),r.getString("currency"),r.getString("state"),context==null?null:json.readValue(context,Context.class),r.getObject("journal_id",UUID.class),r.getString("last_code"),r.getObject("created_at",OffsetDateTime.class).toInstant(),r.getObject("updated_at",OffsetDateTime.class).toInstant());}
 public Row get(String tenant,UUID id){return jdbc.query("SELECT * FROM transfers WHERE integrator_id=? AND id=?",(r,n)->read(r),tenant,id).stream().findFirst().orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"TRANSFER_NOT_FOUND","Transfer not found for this integrator."));}
 @Transactional(timeout=10) public Begin begin(String tenant,String actor,String key,TransferRequest request){
  jdbc.query("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",(org.springframework.jdbc.core.RowCallbackHandler)r->{},tenant.length()+":"+tenant+key);String hash=RequestKeys.hash(json.writeValueAsString(request.canonical()),actor);
  var previous=jdbc.query("SELECT fingerprint,id FROM transfers WHERE integrator_id=? AND idempotency_key=?",(r,n)->List.of(r.getString(1),r.getObject(2,UUID.class).toString()),tenant,key);
  if(!previous.isEmpty()){if(!previous.getFirst().getFirst().equals(hash))throw new ApiException(HttpStatus.CONFLICT,"IDEMPOTENCY_CONFLICT","This transfer key belongs to different financial intent or another caller.");return new Begin(get(tenant,UUID.fromString(previous.getFirst().get(1))),true);}
  UUID id=UUID.randomUUID();jdbc.update("INSERT INTO transfers(id,integrator_id,idempotency_key,actor_id,fingerprint,sender_wallet,recipient_wallet,amount,max_fee,currency,state) VALUES (?,?,?,?,?,?,?,?,?,?,'CREATED')",id,tenant,key,actor,hash,request.senderWalletId(),request.recipientWalletId(),request.amount(),request.maxFee(),request.currency());return new Begin(get(tenant,id),false);
 }
 @Transactional(timeout=10) public UUID claim(String tenant,UUID id){UUID lease=UUID.randomUUID();int rows=jdbc.update("UPDATE transfers SET lease_token=?,lease_until=clock_timestamp()+INTERVAL '120 seconds' WHERE integrator_id=? AND id=? AND state NOT IN ('COMPLETED','REJECTED','CANCELLED') AND (lease_until IS NULL OR lease_until<=clock_timestamp())",lease,tenant,id);return rows==1?lease:null;}
 @Transactional(timeout=10) public Row save(String tenant,UUID id,UUID lease,String state,Context context,UUID journal,String code){int rows=jdbc.update("UPDATE transfers SET state=?,context=?::jsonb,journal_id=?,last_code=?,updated_at=clock_timestamp() WHERE integrator_id=? AND id=? AND lease_token=? AND lease_until>clock_timestamp()",state,context==null?null:json.writeValueAsString(context),journal,code,tenant,id,lease);if(rows!=1)throw new ApiException(HttpStatus.CONFLICT,"LEASE_LOST","Another worker owns this transfer attempt.");return get(tenant,id);}
 public void release(String tenant,UUID id,UUID lease){jdbc.update("UPDATE transfers SET lease_token=NULL,lease_until=NULL WHERE integrator_id=? AND id=? AND lease_token=?",tenant,id,lease);}
 public List<View> list(String tenant,UUID wallet,UUID after,int limit){return jdbc.query("SELECT * FROM transfers WHERE integrator_id=? AND (sender_wallet=? OR recipient_wallet=?) AND (?::uuid IS NULL OR id>?::uuid) ORDER BY id LIMIT ?",(r,n)->view(read(r)),tenant,wallet,wallet,after,after,limit+1);}
 public record Work(String tenant,UUID id){}
 public List<Work> work(){return jdbc.query("SELECT integrator_id,id FROM transfers WHERE state NOT IN ('CREATED','COMPLETED','REJECTED','CANCELLED') AND (lease_until IS NULL OR lease_until<=clock_timestamp()) ORDER BY updated_at,id LIMIT 25",(r,n)->new Work(r.getString(1),r.getObject(2,UUID.class)));}
 public List<UUID> recoverable(String tenant,UUID after,int limit){return jdbc.query("SELECT id FROM transfers WHERE integrator_id=? AND state NOT IN ('CREATED','COMPLETED','REJECTED','CANCELLED','CANCELLED') AND (lease_until IS NULL OR lease_until<=clock_timestamp()) AND (?::uuid IS NULL OR id>?::uuid) ORDER BY id LIMIT ?",(r,n)->r.getObject(1,UUID.class),tenant,after,after,limit);}
}
